package main

import (
	"errors"
	"time"

	tea "github.com/charmbracelet/bubbletea"
)

// Ui is the facade of the UI: one typed handle per code name.
type Ui struct {
	*Core
	opts []tea.ProgramOption
	Status *TextHandle // Text
	NameInput *InputHandle // TextInput
	SubmitBtn *ButtonHandle // Button
	Agree *CheckHandle // Checkbox
	Color *SelectHandle // Select
	Progress *ProgressHandle // ProgressBar
	Results *TableHandle // Table
	Files *ListHandle // List
	Pages *TabsHandle // Tabs
	Panel *ContainerHandle // Box
	Inner *TextHandle // Text
	Confirm *ModalHandle // Modal
}

// NewUi creates the UI and its handles. Without options it runs on the alternate screen.
func NewUi(opts ...tea.ProgramOption) *Ui {
	if len(opts) == 0 {
		opts = []tea.ProgramOption{tea.WithAltScreen(), tea.WithMouseCellMotion()}
	}
	core := NewCore()
	ui := &Ui{Core: core, opts: opts}
	ui.Status = NewTextHandle(core.Define("status", "Text", StatesHideOnly, StateActive, map[string]any{
		"text": "Ready",
	}))
	ui.NameInput = NewInputHandle(core.Define("name_input", "TextInput", StatesAll, StateActive, map[string]any{
		"value": "",
		"placeholder": "your name",
	}))
	ui.SubmitBtn = NewButtonHandle(core.Define("submit_btn", "Button", StatesNoReadonly, StateActive, map[string]any{
		"label": "Send",
	}))
	ui.Agree = NewCheckHandle(core.Define("agree", "Checkbox", StatesAll, StateActive, map[string]any{
		"checked": false,
		"label": "I agree",
	}))
	ui.Color = NewSelectHandle(core.Define("color", "Select", StatesAll, StateActive, map[string]any{
		"value": "",
		"options": []string{"Red", "Green", "Blue"},
	}))
	ui.Progress = NewProgressHandle(core.Define("progress", "ProgressBar", StatesNoReadonly, StateActive, map[string]any{
		"value": float64(0),
		"max": float64(100),
	}))
	ui.Results = NewTableHandle(core.Define("results", "Table", StatesAll, StateActive, map[string]any{
		"columns": []string{"Column 1", "Column 2"},
		"rows": [][]string{{"Cell 1", "Cell 2"}, {"Cell 3", "Cell 4"}},
	}))
	ui.Files = NewListHandle(core.Define("files", "List", StatesAll, StateActive, map[string]any{
		"items": []string{"Item 1", "Item 2", "Item 3"},
		"selected": 0,
	}))
	ui.Pages = NewTabsHandle(core.Define("pages", "Tabs", StatesAll, StateActive, map[string]any{
		"active_tab": 0,
	}))
	ui.Panel = NewContainerHandle(core.Define("panel", "Box", StatesHideOnly, StateActive, nil))
	ui.Inner = NewTextHandle(core.Define("inner", "Text", StatesHideOnly, StateActive, map[string]any{
		"text": "Inside the panel",
	}))
	ui.Confirm = NewModalHandle(core.Define("confirm", "Modal", StatesHideOnly, StateActive, map[string]any{
		"title": "Sure?",
		"open": false,
	}))
	core.Define("~text", "Text", StatesHideOnly, StateActive, map[string]any{
		"text": "Really?",
	})
	return ui
}

// Start runs the UI in its own goroutine and returns when it is ready (or with an error).
func (u *Ui) Start() error {
	if !u.MarkStarted() {
		return errors.New("ui: already started")
	}
	errc := make(chan error, 1)
	go func() { errc <- u.runProgram() }()
	if u.WaitReady(10 * time.Second) {
		return nil
	}
	select {
	case err := <-errc:
		if err != nil {
			return err
		}
	default:
	}
	return errors.New("ui: the UI did not start")
}

// Run runs the UI on the calling goroutine and fn (your program) next to it. It returns when the
// UI is closed.
func (u *Ui) Run(fn func(*Ui)) error {
	if !u.MarkStarted() {
		return errors.New("ui: already started")
	}
	go u.CatchPanics(func() {
		if u.WaitReady(10 * time.Second) {
			fn(u)
		}
	})
	return u.runProgram()
}

func (u *Ui) runProgram() error {
	p := tea.NewProgram(newModel(u), u.opts...)
	r := &teaRenderer{p: p, wake: make(chan struct{}, 1), done: make(chan struct{})}
	u.Attach(r)
	go r.pump()
	_, err := p.Run()
	close(r.done)
	u.MarkClosed()
	return err
}

// Send delivers a Bubble Tea message to the UI (tests use it to simulate keys).
func (u *Ui) Send(msg tea.Msg) {
	if r, ok := u.Renderer().(*teaRenderer); ok && !u.Closed() {
		r.p.Send(msg)
	}
}

// Frame returns what the UI currently shows ("" if it is not running).
func (u *Ui) Frame() string {
	r, ok := u.Renderer().(*teaRenderer)
	if !ok || u.Closed() {
		return ""
	}
	reply := make(chan string, 1)
	r.p.Send(frameMsg{reply: reply})
	select {
	case s := <-reply:
		return s
	case <-time.After(2 * time.Second):
		return ""
	}
}

// refreshMsg wakes the program after another goroutine changed the store.
type refreshMsg struct{}

// frameMsg asks the program for its current View.
type frameMsg struct{ reply chan string }

// teaRenderer connects the runtime to Bubble Tea. Refresh must never block (it can be called
// from Update), so wake-ups are coalesced and sent by a separate goroutine.
type teaRenderer struct {
	p    *tea.Program
	wake chan struct{}
	done chan struct{}
}

func (r *teaRenderer) Refresh() {
	select {
	case r.wake <- struct{}{}:
	default:
	}
}

func (r *teaRenderer) Stop() { go r.p.Quit() }

func (r *teaRenderer) pump() {
	for {
		select {
		case <-r.wake:
			r.p.Send(refreshMsg{})
		case <-r.done:
			return
		}
	}
}
